<?php
$urls=array_filter(array_slice($argv,1,999),fn($x)=>str_starts_with($x,'http'));$re='/[a-z0-9._%+-]+\s*(?:@|\[at\]|\(at\))\s*[a-z0-9.-]+\s*(?:\.|\[dot\]|\(dot\))\s*[a-z]{2,}/i';$out=[];foreach($urls as $u){$ctx=stream_context_create(['http'=>['header'=>'User-Agent: EmailKeywordCrawler/1.0\r\n','timeout'=>15]]);$t=@file_get_contents($u,false,$ctx)?:'';preg_match_all($re,$t,$ms);foreach($ms[0] as $m){$e=strtolower(preg_replace('/\s+/','',$m));$e=str_replace(['[at]','(at)','[dot]','(dot)'],['@','@','.','.'],$e);$out[$e]=$u;}echo json_encode(['event'=>'page','url'=>$u,'emails'=>count($out),JSON_UNESCAPED_SLASHES]).PHP_EOL;}file_put_contents('emails.txt',implode(PHP_EOL,array_keys($out)));$f=fopen('emails.csv','w');fputcsv($f,['email','source_url']);foreach($out as $e=>$u)fputcsv($f,[$e,$u]);fclose($f);
